from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
helpers={"__file__":str(ROOT/"scripts/build-electrolyte-pages.py")}
exec((ROOT/'scripts/build-electrolyte-pages.py').read_text().split('mg_inputs=')[0],helpers)
number,stock,results,shell=[helpers[k] for k in ['number','stock','results','shell']]

p=ROOT/'dist/magnesium.html';s=p.read_text()
if 'mBloodwork' not in s:
    guide=f'''<section class="panel mg-reference"><h2>Bloodwork → workbook dose option</h2><p><b>Total Mg guide from your sheet: 1.5–2.5 mg/dL.</b> Use the reference interval printed on the bloodwork if it differs. These fields are for total Mg, not ionized Mg.</p><div class="patient-grid">{number('mBloodwork','Current total magnesium (optional)','mg/dL',required=False)}{number('mLower','Lab lower limit','mg/dL','1.5','.001')}{number('mUpper','Lab upper limit','mg/dL','2.5','.001')}</div><label>Is hypokalemia refractory to K supplementation?<select id="mRefractory"><option value="unknown">Not assessed</option><option value="yes">Yes</option><option value="no">No</option></select></label><div id="mInterpretation" class="interpretation" role="status">Below the lower limit: review the 1 mEq/kg/day option. Within range with refractory K: review the 0.5 option. Above range: neither workbook replacement option applies.</div><p class="help">The result helps locate a workbook option; it does not automatically prescribe or select a dose.</p></section>'''
    s=s.replace('<form data-electrolyte>','<form data-electrolyte>'+guide,1)
    s=s.replace('<tr><th scope="row">Low extracellular Mg — workbook option</th>','<tr id="mContext0"><th scope="row" id="mBand0">Below lab lower limit</th>').replace('<tr><th scope="row">Normal Mg with refractory K — workbook option</th>','<tr id="mContext1"><th scope="row" id="mBand1">Within lab interval + refractory K</th>')
    s=s.replace('Dose units are mEq/kg/day.','Higher-dose option: 1 mEq/kg/day for low Mg. Lower-dose option: 0.5 mEq/kg/day for within-range Mg with refractory K, as in the workbook. Dose units are mEq/kg/day.')
p.write_text(s)
p=ROOT/'dist/phosphate.html';s=p.read_text()
if 'pKRateHero' not in s:
    hero='''<section id="pKHeroPanel" tabindex="-1" class="panel potassium-contribution" aria-labelledby="pKHeroTitle"><h2 id="pKHeroTitle">Potassium delivered by the selected KPhos dose</h2><div class="contribution-grid" aria-live="polite"><div><span>K RATE FROM KPHOS</span><strong id="pKRateHero">—</strong><b>mEq/kg/hr</b></div><div><span>POTASSIUM PER HOUR</span><strong id="pKHourlyHero">—</strong><b>mEq/hr</b></div><div><span>POTASSIUM IN THIS PREPARATION</span><strong id="pKAmountHero">—</strong><b>mEq total</b></div></div><p id="pKHeroStatus" class="help">Select a phosphate rate to show its potassium contribution here.</p></section>'''
    s=s.replace('<section class="panel results" id="pResultSection"',hero+'<section class="panel results" id="pResultSection"',1)
p.write_text(s)

patient=f'''<form data-electrolyte><section class="panel"><h2>1. Patient & context</h2><div class="patient-grid">{number('nWeight','Patient weight','kg',minimum='.001')}{number('nCurrent','Measured patient Na','mEq/L',minimum='.001')}<label>Chronicity<select id="nType"><option value="chronic">Chronic / uncertain duration</option><option value="acute">Confirmed acute</option></select></label></div><p class="help">Measured patient Na and target fluid Na are separate values. Choose the workflow using the patient’s laboratory interval and clinical context.</p></section></form>'''
workflows='''<div class="workflow-grid"><section class="panel workflow-card"><h2>HIGH sodium · Hypernatremia</h2><ol><li>Assess perfusion, neurologic signs, hydration, and chronicity.</li><li>Restore perfusion first if hypovolemic; investigate water access, water losses, renal concentrating ability, and sodium exposure.</li><li>Plan controlled free-water replacement; tailor fluid sodium when needed and recheck the measured response.</li></ol><button type="button" class="workflow-choice" data-path="hyper" aria-pressed="true">Use hypernatremia workflow</button></section><section class="panel workflow-card"><h2>LOW sodium · Hyponatremia</h2><ol><li>Assess neurologic urgency and perfusion first.</li><li>Confirm the result and glucose effect; assess volume status and chronicity.</li><li>Investigate the cause, choose the fluid and initial correction plan, then recheck sodium.</li></ol><button type="button" class="workflow-choice" data-path="hypo" aria-pressed="false">Use hyponatremia workflow</button></section></div>'''
hyper=f'''<section id="hyperWorkflow"><div class="notice">For chronic hypernatremia, reference limits are 0.5 mEq/L/hr and 10–12 mEq/L/day. Free-water estimates do not replace perfusion resuscitation. <a href="sources.html#sodium-source">AAHA reference</a>.</div><div class="sodium-two"><form data-electrolyte><section class="panel"><h2>2. Free-water replacement estimate</h2>{number('nGoal','Clinician-selected patient Na target','mEq/L',minimum='.001')}{number('nHours','Custom duration (optional)','hours',minimum='.001',required=False)}<p class="help">Blank duration uses 0.5 mEq/L/hr for chronic or 1 mEq/L/hr for confirmed acute context. The body-water fraction remains 0.6.</p><button type="reset">Clear free-water target</button></section></form>{results('nWater')}</div></section>'''
hypo='''<section id="hypoWorkflow" hidden><section class="panel"><h2>2. Hyponatremia workup & initial priorities</h2><div class="sodium-two"><div><h3>Urgent assessment</h3><p>Seizures or marked neurologic compromise require urgent evaluation for symptomatic hyponatremia; consider other causes concurrently. Stabilize hypoperfusion with a fluid selected to avoid an abrupt sodium shift.</p><p>AAHA describes 2–6 mL/kg of 3–7.5% NaCl over 10–15 minutes for symptomatic cases, with reassessment. The mixing cards below are not this rescue-bolus protocol.</p></div><div><h3>Confirm & investigate</h3><ul><li>Repeat Na if unexpected; review assay/sample issues, glucose, and other chemistry findings.</li><li>Review GI/renal losses, third spacing, water intake, diuretics, desmopressin, and recent fluids; assess hydration and volume status.</li><li>Obtain urinalysis/USG and renal assessment as indicated. Consider measured osmolality and urine studies if the cause remains unclear.</li><li>In dogs with compatible findings, investigate hypoadrenocorticism; consider cardiac/hepatic/renal disease or inappropriate water retention according to the examination.</li></ul></div></div><details><summary>Canine Addison’s testing reference</summary><p>AAHA: resting cortisol &gt;2 µg/dL strongly excludes hypoadrenocorticism when assay-interfering glucocorticoids are absent. A lower result is not diagnostic; confirm with ACTH stimulation when indicated. Na:K ratio alone is not diagnostic.</p><a href="sources.html#hyponatremia-workup">Sources and limitations</a></details><p class="help">Chronic/uncertain cases: use a conservative starting plan within 0.5 mEq/L/hr and 10–12 mEq/L/day; monitor the actual response. This is a focused ER workflow, not an exhaustive differential list.</p></section></section>'''

cards=''
for i,(name,na,k) in enumerate([('LRS',130,4),('Plasma-Lyte',140,5),('0.9% NaCl',154,0)]):
    cards+=f'''<section class="fluid-card"><h3>{name}</h3><p>Base Na <b>{na} mEq/L</b><br><small>Carrier K before mixing: {k} mEq/L</small></p><span class="card-output-label" id="nCardStockLabel{i}">7.2% NaCl TO ADD TO {name}</span><strong id="nCardMl{i}">— mL</strong><p id="nCardCarrier{i}">Carrier: — mL</p><p id="nCardNote{i}" class="help">Enter target fluid Na and volume.</p><button type="button" data-base="{na}" data-fluid="{name}" aria-pressed="false">Select {name} & show math</button></section>'''
n_stock=stock('n',[('nStock','Stock / replacement Na','mEq/L','1232','0')],'Locked default: 7.2% NaCl at the workbook’s 1232 mEq/L. Choose 3% or 7.5% explicitly if those match your product, or unlock for a custom label concentration. Sodium-free replacement is formulation math only; it is not a routine hyponatremia treatment instruction.')
mix=f'''<section class="panel" id="mixingTool"><h2>3. Compare base fluids + hypertonic NaCl</h2><form data-electrolyte><div class="patient-grid">{number('nVolume','Specified final fluid volume','mL',minimum='.001')}{number('nFluidGoal','Target FLUID sodium','mEq/L')}<label>Stock / replacement<select id="nPreset"><option value="1232">7.2% NaCl — 1232 mEq/L</option><option value="1283">7.5% NaCl — 1283 mEq/L</option><option value="513">3% NaCl — 513 mEq/L</option><option value="0">Sodium-free replacement — 0 mEq/L</option><option value="custom">Custom concentration</option></select></label></div>{n_stock}<input type="hidden" id="nBase" value=""><input type="hidden" id="nFluidName" value=""><p><b>Target FLUID sodium is not the patient sodium target.</b> Each card keeps the final volume fixed: remove carrier volume equal to stock added. Unreachable mixtures are shown explicitly.</p><div class="fluid-card-grid">{cards}</div><p id="nSelectedFluid" class="help">No fluid selected yet.</p><button type="reset">Clear fluid selection & restore stock</button></form></section>{results('nMix')}'''
response=f'''<section id="hypoPlan" hidden><div class="sodium-two"><form data-electrolyte><section class="panel"><h2>4. Hyponatremia starting-plan estimate</h2><p class="help">Uses the selected fluid card and the shared patient weight/Na. Enter all potassium in the administered fluid, including carrier K and additives; K affects this sodium-response equation.</p>{number('hFluidNa','Selected prepared fluid Na','mEq/L').replace('type="number"','type="number" readonly')}{number('hFluidK','TOTAL K in the administered fluid','mEq/L')}{number('hRate','Planned fluid rate','mL/hr',minimum='.001')}{number('hHours','Planning interval','hours','24','.001')}<button type="reset">Clear starting-plan inputs</button><p class="help">The per-liter Adrogué–Madias estimate is scaled to planned volume. This approximate starting estimate omits evolving losses and renal water handling; serial Na measurements take precedence.</p></section></form>{results('hResponse')}</div></section>'''
quick=f'''<details class="panel"><summary>Additional mixing quick math</summary><form data-electrolyte><div class="grid">{number('qVolumeA','Fluid A volume','mL')}{number('qNaA','Fluid A Na','mEq/L','130')}{number('qVolumeB','Fluid B volume','mL')}{number('qNaB','Fluid B Na','mEq/L','0')}</div><button type="reset">Clear quick math</button></form>{results('nQuick')}</details>'''
glucose=f'''<details class="panel"><summary>Check glucose-corrected sodium</summary><form data-electrolyte><div class="patient-grid">{number('gNa','Measured sodium','mEq/L',minimum='.001')}{number('gGlucose','Glucose','mg/dL',minimum='100')}<label>Species<select id="gSpecies"><option value="dog">Canine</option><option value="cat">Feline — extrapolated</option></select></label></div><button type="reset">Clear glucose correction</button></form>{results('nGlucose')}</details>'''
shell('sodium.html','Sodium','Start with patient assessment, then follow the high- or low-sodium path and compare preparation options.',patient+workflows+hyper+hypo+mix+response+glucose+quick,'sodium')
